"""Run after editing assets/data/*.json to refresh the browser-readable banks."""
import json
from pathlib import Path


data_dir = Path(__file__).resolve().parents[1] / 'assets' / 'data'
for source in sorted(data_dir.glob('*.json')):
    payload = json.loads(source.read_text(encoding='utf-8'))
    output = (
        '// Generated by tools/build_question_banks.py; edit the matching JSON file.\n'
        'window.questionBanks = window.questionBanks || {};\n'
        f'window.questionBanks[{json.dumps(source.stem)}] = '
        f'{json.dumps(payload, ensure_ascii=True, separators=(",", ":"))};\n'
    )
    source.with_suffix('.js').write_text(output, encoding='utf-8')
